#undef X

#define X(n, p, c) \
    int n(const char *l, mcmc_tokenizer_t *t, int idx, p *val) { \
        int tlen = 0; \
        const char *tok = _mcmc_token(l, t, idx, &tlen); \
        if (tlen > 1) { \
            return c(tok+1, tlen-1, val); \
        } \
